pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address currentOwner, address newOwner) public {
        vm.assume(currentOwner != address(0));

        vm.prank(address(0));
        c.transferOwnership(currentOwner);

        address ownerNow = c.owner();

        vm.prank(currentOwner);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == true && c.owner() == newOwner);
    }
}
